  let(:credentials) do
    { api_key: 'test-api_key', callback_secret: 'test-callback_secret', merchant_id: 'string' }
  end
  let(:service) { described_class.new(client: Provider::HttpClient.new, credentials: credentials) }
  let(:requests) { [] }
  # The platform operation built from fixtures.json (the create request and its success response).
  let(:operation) do
    Provider::Operation.new(
      id: 'string',
      amount: 100,
      currency: 'RUB',
      provider_operation_id: 'string',
      payout_requisite: { 'card' => { 'card_number' => 'test-card_number', 'name' => 'test-name' } }
    )
