    it 'maps HTTP 429 to failure(:too_many_requests, provider.rate_limit) with Retry-After' do
      stub_provider(:post, url, 429, fixture('create_request', 'response_429'), headers: { 'Retry-After' => '60' })

      result = service.create_request(operation, 'card')

      expect([result.error, result.code]).to eq([:too_many_requests, 'provider.rate_limit'])
      expect(result.details[:provider_code]).to eq('REQUEST_LIMIT')
      expect(result.details[:retry_after]).to eq(60)
    end

    it 'maps HTTP 500 to failure(:provider_error, provider.internal_error)' do
      stub_provider(:post, url, 500, fixture('create_request', 'response_500'))

      result = service.create_request(operation, 'card')

      expect([result.error, result.code]).to eq([:provider_error, 'provider.internal_error'])
      expect(result.details[:provider_code]).to eq('INTERNAL_FAILURE')
    end

    it 'refuses an unknown request_method without calling the provider' do
      result = service.create_request(operation, 'unsupported')

      expect([result.error, result.code]).to eq([:unprocessable_entity, 'unsupported_request_method'])
      expect(WebMock).not_to have_requested(:any, /./)
